function idsToCreate(desired, current) {
  const have = new Set(current.map((r) => r.id));
  return desired.filter((r) => !have.has(r.id)).map((r) => r.id);
}

function idsToDelete(desired, current) {
  const want = new Set(desired.map((r) => r.id));
  return current.filter((r) => !want.has(r.id)).map((r) => r.id);
}

function needsUpdate(declaredSize, stateSize) {
  return declaredSize !== stateSize;
}

function hasDrift(stateSize, actualSize) {
  return stateSize !== actualSize;
}

function classify(declaredSize, stateSize) {
  if (stateSize === null) return "create";
  return declaredSize !== stateSize ? "update" : "none";
}

function idsInBoth(a, b) {
  const inB = new Set(b.map((r) => r.id));
  return a.filter((r) => inB.has(r.id)).map((r) => r.id);
}

function isNoOp(plan) {
  return plan.create.length === 0 && plan.update.length === 0 && plan.delete.length === 0;
}

function countChanges(plan) {
  return plan.create.length + plan.update.length + plan.delete.length;
}

function planIds(desired, current) {
  const have = new Map(current.map((r) => [r.id, r.size]));
  const want = new Map(desired.map((r) => [r.id, r.size]));
  return {
    create: desired.filter((r) => !have.has(r.id)).map((r) => r.id),
    update: desired
      .filter((r) => have.has(r.id) && have.get(r.id) !== r.size)
      .map((r) => r.id),
    delete: current.filter((r) => !want.has(r.id)).map((r) => r.id),
  };
}

function driftIds(state, actual) {
  const live = new Map(actual.map((r) => [r.id, r.size]));
  return state.filter((r) => live.get(r.id) !== r.size).map((r) => r.id);
}

function planSummary(desired, current) {
  const have = new Map(current.map((r) => [r.id, r.size]));
  const want = new Set(desired.map((r) => r.id));
  const create = desired.filter((r) => !have.has(r.id)).length;
  const update = desired.filter((r) => have.has(r.id) && have.get(r.id) !== r.size).length;
  const del = current.filter((r) => !want.has(r.id)).length;
  return `${create} to create, ${update} to update, ${del} to delete`;
}
